import{_ as e,o as t,c as r,a2 as a}from"./chunks/framework.D66Xq0Kv.js";const p=JSON.parse('{"title":"Workbooks","description":"","frontmatter":{"title":"Workbooks"},"headers":[],"relativePath":"docs/concepts/workbooks.md","filePath":"docs/concepts/workbooks.md","lastUpdated":1792651611000}'),s={name:"docs/concepts/workbooks.md"};function n(d,o,i,c,k,h){return t(),r("div",null,[...o[0]||(o[0]=[a('<h1 id="workbooks" tabindex="-1">Workbooks <a class="header-anchor" href="#workbooks" aria-label="Permalink to &quot;Workbooks&quot;">​</a></h1><p>A <a href="/docs/concepts/projects">project</a> answers questions about one part of your finances — your spending, say, or one set of brokerage accounts. A <strong>workbook</strong> brings several projects together, so you can ask questions that depend on all of them at once: what you&#39;re worth, how your spending relates to your investments, whether you could retire.</p><p>A workbook holds no statements of its own. It draws on the projects you choose, and its views update automatically as those projects change.</p><h2 id="projects-and-workbooks" tabindex="-1">Projects and workbooks <a class="header-anchor" href="#projects-and-workbooks" aria-label="Permalink to &quot;Projects and workbooks&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>Project</th><th>Workbook</th></tr></thead><tbody><tr><td>Holds</td><td>Your documents and statement data</td><td>A selection of your projects</td></tr><tr><td>Answers</td><td>One part of the picture</td><td>Questions that span projects</td></tr><tr><td>Example</td><td>Spending &amp; Income</td><td>Net worth across spending, investments and assets</td></tr></tbody></table><p>A workbook is built from projects, never from other workbooks. To change what a workbook shows, change its projects or add and remove projects from it.</p><h2 id="kinds-of-workbook" tabindex="-1">Kinds of workbook <a class="header-anchor" href="#kinds-of-workbook" aria-label="Permalink to &quot;Kinds of workbook&quot;">​</a></h2><ul><li><strong>Standard Workbook</strong> — investment, combined spending, and net worth views across the projects you choose. This was previously called Combined Finance; see <a href="/docs/personal-finance/combined-finance">Combined finance</a> for what it shows.</li><li><strong>Retirement Planning</strong> — projects your retirement path from the projects you choose. See <a href="/docs/personal-finance/retirement">Retirement</a>.</li></ul><h2 id="creating-and-managing-workbooks" tabindex="-1">Creating and managing workbooks <a class="header-anchor" href="#creating-and-managing-workbooks" aria-label="Permalink to &quot;Creating and managing workbooks&quot;">​</a></h2><p>The <strong>Dashboard</strong> shows accounts and documents grouped by project, with connections to the workbooks that use them. You need at least one project before you can create a workbook.</p><ol><li>Choose <strong>New Workbook</strong>, pick its kind, and give it a name (or accept the default, such as &quot;My Workbook&quot;).</li><li>Tick the projects it should draw on.</li><li>Later, use <strong>Add Sources</strong> from the workbook to bring in more projects. Remove them from the workbook&#39;s Sources page.</li></ol><p>Workbooks can be renamed and deleted like projects. Deleting a project that a workbook uses asks you to confirm first, and tells you which workbooks it affects.</p><h2 id="demo-data-stays-separate" tabindex="-1">Demo data stays separate <a class="header-anchor" href="#demo-data-stays-separate" aria-label="Permalink to &quot;Demo data stays separate&quot;">​</a></h2><p>Demo projects hold invented numbers, so they never share a workbook with your own. A workbook is either built from demo projects or from your real ones, not a mix. The <strong>Demo Retirement</strong> workbook lets you explore the whole workflow safely before you add real statements.</p>',14)])])}const b=e(s,[["render",n]]);export{p as __pageData,b as default};
